OUT = os.path.join(TASK, "3_execution")

def load_json(name):
    path = os.path.join(SRC, name)
    with open(path) as f:
        return json.load(f)

# Load indexes
cellline_index = load_json("cellline_index.json")
drug_index = load_json("drug_index.json")
gene_index = load_json("gene_index.json")
function_index_raw = load_json("function_index.json")

# Extract actual entity names from indexes
cell_names = set()
if isinstance(cellline_index, dict):
    for v in cellline_index.values():
        if isinstance(v, list):
            cell_names.update(v)
        elif isinstance(v, str):
            cell_names.add(v)

drug_names_lower = set()
if isinstance(drug_index, dict):
    for k,v in drug_index.items():
        drug_names_lower.add(k.lower())

gene_keys_lower = set()
if isinstance(gene_index, dict):
    gene_keys_lower = set(k.lower() for k in gene_index.keys())

# Function names
function_names = set()
if isinstance(function_index_raw, dict):
    meta = function_index_raw.get("meta", {})
    aliases = function_index_raw.get("aliases", {})
    for k in meta.keys():
        function_names.add(k.lower())
    for v in aliases.values():
        if isinstance(v, list):
            for a in v:
                function_names.add(a.lower())
        elif isinstance(v, str):
            function_names.add(v.lower())

# T-013 historical demo entities (likely T-042 demo cases)
forward_entities = {
    "gene": ["EGFR"],
    "cell_line": ["A549"],
    "function_terms": ["HALLMARK_INTERFERON_ALPHA_RESPONSE", "HALLMARK_INTERFERON_GAMMA_RESPONSE",
                       "HALLMARK_EPITHELIAL_MESENCHYMAL_TRANSITION", "HALLMARK_MYC_TARGETS_V2",
                       "HALLMARK_E2F_TARGETS", "HALLMARK_G2M_CHECKPOINT", "HALLMARK_MYC_TARGETS_V1"]
}

reverse_entities = {
    "function_terms": ["HALLMARK_APOPTOSIS", "HALLMARK_MYC_TARGETS_V1"],
    "cell_line": ["A549"],
    "gene_candidates": ["THTPA", "SCD", "LRP6", "CD1C", "DHRS3", "STH", "ACAN", "SPHK2"]
}

# Check coverage
gaps = []

for entity_type, entities in forward_entities.items():
    for entity in entities:
        if entity_type == "gene" and entity.lower() not in gene_keys_lower:
            gaps.append({"demo_case": "forward", "entity_type": "gene", "entity": entity, "found": False})
        if entity_type == "cell_line" and entity not in cell_names:
            gaps.append({"demo_case": "forward", "entity_type": "cell_line", "entity": entity, "found": False})
        if entity_type == "function_terms" and entity.lower() not in function_names:
            gaps.append({"demo_case": "forward", "entity_type": "function_term", "entity": entity, "found": False})

for entity_type, entities in reverse_entities.items():
    for entity in entities:
        if entity_type == "gene_candidates" and entity.lower() not in gene_keys_lower:
            gaps.append({"demo_case": "reverse", "entity_type": "gene", "entity": entity, "found": False})
        if entity_type == "cell_line" and entity not in cell_names:
            gaps.append({"demo_case": "reverse", "entity_type": "cell_line", "entity": entity, "found": False})
        if entity_type == "function_terms" and entity.lower() not in function_names:
            gaps.append({"demo_case": "reverse", "entity_type": "function_term", "entity": entity, "found": False})

step4 = {
    "method": "Cross-referenced T-013 historical demo entities against T-021 indexes",
    "note": "T-042 has NOT been executed; demo cases are not finalized. Using T-013 historical evidence as best available proxy for M1 demo requirements",
    "t042_status": "active / check_failed / not_started — no m1_demo_cases.yaml exists",
    "historical_proxy_entities": {
        "forward": forward_entities,
        "reverse": reverse_entities
    },
    "coverage_gaps": gaps,
    "gap_count": len(gaps)
}

with open(os.path.join(OUT, "step4_coverage_gap.json"), "w") as f:
    json.dump(step4, f, indent=2)
print(json.dumps(step4, indent=2, default=str))
PYEOF

