gi=json.load(open(os.path.join(SRC,'gene_index.json')))
fi=json.load(open(os.path.join(SRC,'function_index.json')))
cells = set()
for v in ci.values():
    if isinstance(v, list): cells.update(v)
    elif isinstance(v, str): cells.add(v)
function_keys = set(fi.get('meta',{}).keys())
# Also check aliases
aliases = fi.get('aliases', {})
function_names = function_keys | set(aliases.keys())
for v in aliases.values():
    if isinstance(v, list): function_names.update(v)
    elif isinstance(v, str): function_names.add(v)
# Demo entities to check
demo_entities = {
    'candidate_gene': ['egfr', 'thtpa', 'scd', 'lrp6', 'cd1c', 'dhrs3', 'sth', 'acan', 'sphk2', 'hla-a'],
    'cell_line': ['A549'],
