}
genes_lower = set(k.lower() for k in gi.keys())
print('=== Coverage Check ===')
for cat, ents in demo_entities.items():
    for e in ents:
        if cat == 'candidate_gene':
            found = e.lower() in genes_lower
        elif cat == 'cell_line':
            found = e in cells
        elif cat == 'function_term':
            found = e in function_names or e.lower() in function_names
        status = 'OK' if found else 'MISSING'
        print(f'  {status}: {cat} = {e}')
print(f'\nCell count: {len(cells)}, Gene count: {len(genes_lower)}, Function count: {len(function_names)}')
